import 'dart:convert';

import 'package:authentication/backup/uri_backup_import.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('encrypted URI fixture decrypts on the active platform', () async {
    final bytes = base64Decode(
      '',
    );
    final plaintext = await decryptUriBackup(bytes, password: 'test');
    expect(parseUriBackup(plaintext).accounts.isNotEmpty, true);
  });
}
